def backfill_legacy_video_modes(apps, schema_editor):
    """Identify existing HLS/Drive assets and link only unique legacy slugs."""
    alias = schema_editor.connection.alias
    VideoAsset = apps.get_model("videohosting", "VideoAsset")
    CourseLesson = apps.get_model("courses", "CourseLesson")
    skipped = []

    for asset in VideoAsset.objects.using(alias).select_related("provider").all().iterator():
        if asset.master_playlist.strip():
            mode, protection = "hls", "encrypted"
        elif asset.source_file_id and asset.provider_id and asset.provider.code == "google_drive":
            mode, protection = "raw", "gated"
        else:
            continue

        VideoAsset.objects.using(alias).filter(pk=asset.pk).update(
            playback_mode=mode,
            protection=protection,
        )

        course_slug, separator, lesson_id = asset.slug.partition("--")
        if not separator or not course_slug or not lesson_id:
            continue
        matches = list(
            CourseLesson.objects.using(alias)
            .filter(lesson_id=lesson_id, module__course__slug=course_slug)
            .values_list("pk", "video_asset_id")[:2]
        )
        if len(matches) == 1 and matches[0][1] in (None, asset.pk):
            CourseLesson.objects.using(alias).filter(pk=matches[0][0]).update(
                video_asset_id=asset.pk,
                kind="video",
            )
        else:
            skipped.append(asset.slug)

    if skipped:
        import logging

        logging.getLogger(__name__).warning(
            "Phase 4 video backfill skipped ambiguous lesson links for asset slugs: %s",
            ", ".join(skipped),
        )


